# Jenkins: wipe workspace before each build (hygiene for persistent agents)
// Jenkinsfile (declarative)
agent any
stages {
  stage('Prep') {
    steps {
      cleanWs()          // delete workspace before starting
      checkout scm
    }
  }
}
# GitHub Actions equivalent: every job already gets a fresh VM - nothing to do

pipeline {
  agent { label 'linux' }
  options { timeout(time: 30, unit: 'MINUTES') }
  stages {
    stage('Build') {
      steps { sh 'npm ci && npm run build' }
    }
    stage('Test') {
      steps { sh 'npm test' }
      post { always { junit 'reports/*.xml' } }
    }
    stage('Deploy') {
      when { branch 'main' }
      steps { sh './deploy.sh' }
    }
  }
}

// vars/standardBuild.groovy
def call(Map cfg) {
  stage('Build') { sh "${cfg.buildCmd}" }
  stage('Test') {
    sh "${cfg.testCmd}"
    junit 'reports/*.xml'
  }
  stage('Scan') { sh 'trivy image ${cfg.imageName}' }
}
// Jenkinsfile consumer:
@Library('acme-lib@1.x') _
standardBuild(buildCmd: 'npm ci && npm run build',
              testCmd: 'npm test', imageName: 'acme/app')

pipeline {
  stages {
    stage('Deploy') {
      steps {
        withCredentials([
          string(credentialsId: 'prod-api-token', variable: 'API_TOKEN'),
          usernamePassword(credentialsId: 'registry-creds',
            usernameVariable: 'REG_USER', passwordVariable: 'REG_PASS')
        ]) {
          sh './deploy.sh'   // uses $API_TOKEN, $REG_USER, $REG_PASS
        }                     // values masked in console output
      }
    }
  }
}

// shipping dark, releasing via flag
function checkout(req) {
  if (flags.isEnabled('new-checkout', req.user)) {
    return newCheckoutFlow(req);   // 10% of users
  }
  return legacyCheckoutFlow(req);  // everyone else
}
// incident response: flags.disable('new-checkout')
// -> 100% back on legacy flow in seconds, no deploy

